      const roiData = {
        x: 0,
        y: 0,
        w: 1,
        h: 1,
        preset: preset,
        low_hz: lowHz,
        high_hz: highHz,
        alpha: 8
      };

      console.log(
        "Sending ROI:",
        roiData
      );

      const roiResponse = await fetch(
        "http://127.0.0.1:8000/api/jobs/" +
          jobId +
          "/roi",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify(roiData)
        }
      );

      if (!roiResponse.ok) {
        throw new Error(
          "ROI submission failed. Status: " +
          roiResponse.status
        );
      }

      const roiResult =
        await roiResponse.json();

      console.log(
        "ROI response:",
        roiResult
      );

      /*
       * STEP 5:
       * Start backend processing / ML
       */
      const processResponse = await fetch(
        "http://127.0.0.1:8000/api/jobs/" +
          jobId +
          "/process",
        {
          method: "POST"
        }
      );

      if (!processResponse.ok) {
        throw new Error(
          "Processing request failed. Status: " +
          processResponse.status
        );
      }

      const processResult =
        await processResponse.json();

      console.log(
        "Processing response:",
        processResult
      );

      /*
       * STEP 6:
       * Store complete analysis information
       */
      const analysisData = {
        job_id: jobId,

        upload: uploadResult,

        roi: roiResult,

        process: processResult,

        file_name: file.name,

        preset: preset,

        low_hz: lowHz,

        high_hz: highHz,

        alpha: 8
      };

      sessionStorage.setItem(
        "motionAmpResult",
        JSON.stringify(analysisData)
      );

      /*
       * Processing completed successfully
       */
      setProcessing(false);

      /*
       * Move to Results page
       */
      if (props.onAnalysisComplete) {
        props.onAnalysisComplete(
          analysisData
        );
      }

    } catch (error) {
      console.error(
        "Motion AMP backend error:",
        error
      );

      setProcessing(false);

      alert(
        "Motion AMP processing failed.\n\n" +
        error.message
      );
    }
  };

  /*
   * Dropzone CSS class
   */
  let dropzoneClass = "dropzone";

  if (isDragging) {
    dropzoneClass =
      "dropzone dropzone--drag";
  }

  /*
   * Start button CSS class
   */
  let startButtonClass = "btn-start";

  if (file) {
    startButtonClass =
      "btn-start btn-start--active";
  }

  return (
    <div className="upload-page page-enter">

      {/* NAVBAR */}

      <nav className="navbar navbar--light">

        <div className="nav-inner">

          <button
            className="btn-back"
            onClick={() =>
              props.onNavigate("landing")
            }
          >
            ← Back
          </button>

          <Logo
            onClick={() =>
              props.onNavigate("landing")
            }
          />

          <span className="step-indicator">
            STEP 1 OF 2 — UPLOAD
          </span>

        </div>

      </nav>

      <div className="upload-layout">

        {/* LEFT SIDE */}

        <div className="upload-main">

          <div className="upload-header">

            <h1 className="upload-title">
              Upload Video
            </h1>

            <p className="upload-subtitle">
              Upload a video of the target
              structure or component for
              motion amplification analysis
            </p>

          </div>

          {/* VIDEO DROPZONE */}

          <div
            className={dropzoneClass}
            onClick={() => {
              if (!videoURL) {
                fileInputRef.current.click();
              }
            }}
            onDragOver={(event) => {
              event.preventDefault();
              setIsDragging(true);
            }}
            onDragLeave={() => {
              setIsDragging(false);
            }}
            onDrop={handleDrop}
          >

            <input
              ref={fileInputRef}
              type="file"
              accept="video/*"
              style={{
                display: "none"
              }}
              onChange={handleFileSelect}
            />

            {!videoURL && (
              <div className="dropzone-content">

                <div className="drop-icon">

                  <svg
                    width="36"
                    height="36"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="#9ca3af"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                  >

                    <polyline points="16 16 12 12 8 16" />

                    <line
                      x1="12"
                      y1="12"
                      x2="12"
                      y2="21"
                    />

                    <path
                      d="M20.39 18.39A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3"
                    />

                  </svg>

                </div>

                <p className="drop-main">
                  Drag &amp; drop your video
                </p>

                <p className="drop-sub">
                  or click to browse files
                </p>

                <p className="drop-formats">
                  MP4 • MOV • AVI • MKV —
                  Up to 2 GB
                </p>

              </div>
            )}

            {videoURL && (
              <div
                className="dropzone-preview"
                onClick={(event) => {
                  event.stopPropagation();
                }}
              >

                <video
                  src={videoURL}
                  controls
                  playsInline
                  preload="metadata"
                />

                <div className="file-info">

                  {file.name}

                  {" · "}

                  {(file.size /
                    (1024 * 1024)
                  ).toFixed(1)}

                  {" MB "}

                  <button
                    style={{
                      background: "none",
                      border: "none",
                      color: "#E8741A",
                      cursor: "pointer",
                      fontSize: 12
                    }}
                    onClick={removeVideo}
                  >
                    Remove
                  </button>

                </div>

              </div>
            )}

          </div>

          {/* ROI SECTION */}

          <div className="roi-section">

            <div className="roi-header">

              <div>

                <h3 className="roi-title">
                  Region of Interest
                </h3>

                <p className="roi-sub">
                  Select the area to focus
                  analysis on
                </p>

              </div>

              <span className="roi-tag">
                Full Frame
              </span>

            </div>

            <div className="roi-canvas-wrap">

              <canvas
                ref={roiCanvasRef}
                className="roi-canvas"
                height={280}
              />

              <div className="roi-hint">
                Drag handles to adjust
              </div>

            </div>

          </div>

        </div>

        {/* RIGHT SIDEBAR */}

        <div className="upload-sidebar">

          {/* FREQUENCY PRESET */}

          <div className="sidebar-card">

            <h3 className="sidebar-title">
              Frequency Preset
            </h3>

            <p className="sidebar-sub">
              Select target vibration range
            </p>

            <div className="preset-list">

              {PRESETS.map((item) => (

                <div
                  key={item.id}
                  className={
                    preset === item.id
                      ? "preset-item preset-item--active"
                      : "preset-item"
                  }
                  onClick={() =>
                    selectPreset(item.id)
                  }
                >

                  <div className="preset-info">

                    <span className="preset-name">
                      {item.name}
                    </span>

                    <span className="preset-tag">
                      {item.tag}
                    </span>

                  </div>

                  <span className="preset-desc">
                    {item.desc}
                  </span>

                </div>

              ))}

              {showCustom && (

                <div className="custom-range-inputs">

                  <div className="custom-input-row">

                    <div className="custom-input-group">

                      <label>
                        Min Hz
                      </label>

                      <input
                        type="number"
                        placeholder="e.g. 5"
                        value={minHz}
                        onChange={(event) => {
                          setMinHz(
                            event.target.value
                          );
                        }}
                      />

                    </div>

                    <div className="custom-input-group">

                      <label>
                        Max Hz
                      </label>

                      <input
                        type="number"
                        placeholder="e.g. 100"
                        value={maxHz}
                        onChange={(event) => {
                          setMaxHz(
                            event.target.value
                          );
                        }}
                      />

                    </div>

                  </div>

                </div>

              )}

            </div>

          </div>

          {/* ANALYSIS SETTINGS */}

          <div className="sidebar-card">

            <h3 className="sidebar-title">
              Analysis Settings
            </h3>

            <div className="settings-list">

              {SETTINGS.map((setting) => (

                <div
                  key={setting.name}
                  className="setting-row"
                >

                  <div>

                    <span className="setting-name">
                      {setting.name}
                    </span>

                    <span className="setting-hint">
                      {setting.hint}
                    </span>

                  </div>

                  <span className="setting-value">
                    {setting.value}
                  </span>

                </div>

              ))}

            </div>

          </div>

          {/* START BUTTON */}

          <button
            className={startButtonClass}
            onClick={startAnalysis}
            disabled={!file || processing}
          >

            {processing &&
              "Processing..."}

            {!processing &&
              file &&
              "Start Analysis"}

            {!processing &&
              !file &&
              "Upload a Video to Continue"}

          </button>

        </div>

      </div>

      {/* PROCESSING OVERLAY */}

      {processing && (
        <ProcessingOverlay />
      )}

    </div>
  );
}
